+import { AppError } from "../errors.js";
+
+/** Finds the API key record for `token`, or throws 401. */
+export function authenticate(store, token) {
+  if (!token) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Ensures `apiKey` has one of `roles`, or throws 403. */
+export function authorize(apiKey, roles) {
+  if (!roles.includes(apiKey.role)) throw new AppError("forbidden");
+}
+
+/** Appends an audit entry to the store. */
+export function recordAudit(store, { time, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { time, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Lists audit entries newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
