+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, authHeaders } from "./helpers.js";
+
+test("missing or unknown key is 401 with unauthorized code", async () => {
+  const { handle } = app();
+  const missing = await handle({ path: "/items" });
+  assert.equal(missing.status, 401);
+  assert.equal(missing.body.error.code, "unauthorized");
+
+  const unknown = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(unknown.status, 401);
+  assert.equal(unknown.body.error.code, "unauthorized");
+
+  const malformed = await handle({ path: "/items", headers: { authorization: "Basic abc" } });
+  assert.equal(malformed.status, 401);
+  assert.equal(malformed.body.error.code, "unauthorized");
+});
+
+test("viewer may only read (GET) and not read /audit", async () => {
+  const { handle } = app();
+  const headers = authHeaders("viewer");
+  assert.equal((await handle({ path: "/items", headers })).status, 200);
+
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", headers, body: { portions: 1 } });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+
+  const audit = await handle({ path: "/audit", headers });
+  assert.equal(audit.status, 403);
+  assert.equal(audit.body.error.code, "forbidden");
+});
+
+test("cook may cook, record waste, log temperatures and enter stock-take counts", async () => {
+  const { handle } = app();
+  const manager = authHeaders("manager");
+  const cook = authHeaders("cook");
+
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } })).body;
+
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cook, body: { qty: 0.5, reason: "spoiled" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cook, body: { batchId: 6, counted: 12 } })).status, 200);
+
+  for (const req of [
+    { method: "POST", path: `/stocktakes/${take.id}/finish` },
+    { method: "POST", path: "/stocktakes", body: { location: "fridge" } },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: ["celery"] } },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 5 }] } },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: cook });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("audit logs mutating requests and GET /audit lists newest first for managers", async () => {
+  const { handle } = app();
+  const cook = authHeaders("cook");
+  const manager = authHeaders("manager");
+
+  await handle({ path: "/items", headers: cook });
+  await handle({ method: "POST", path: "/recipes/2/cook", headers: cook, body: { portions: 100 } });
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 1 } });
+  await handle({ method: "POST", path: "/temperatures", headers: manager, body: { location: "fridge", celsius: 4 } });
+
+  const audit = await handle({ path: "/audit", headers: manager });
+  assert.equal(audit.status, 200);
+  assert.equal(audit.body.length, 2);
+  assert.deepEqual(audit.body[0], {
+    time: "2026-10-28T10:00:00.000Z",
+    keyName: "manager",
+    method: "POST",
+    path: "/temperatures",
+    status: 201,
+  });
+  assert.deepEqual(audit.body[1], {
+    time: "2026-10-28T10:00:00.000Z",
+    keyName: "cook",
+    method: "POST",
+    path: "/recipes/1/cook",
+    status: 200,
+  });
+});
